CREATE OR REPLACE VIEW reporting.vw_extended_dtc_detail AS SELECT r.report_id,r.file_id,r.file_name,r.file_path,r.vin,r.sw_i_step,r.sa_codes,d.dtc_event_id,d.source_row_number,d.ecu_name,d.dtc_code,d.description,d.fault_category,d.normalized_fault_category,d.status,d.occurrence_counter,d.aging_counter,d.priority,d.healing_counter,d.debounce_counter,d.severity,d.first_detected,d.last_detected,d.confirmation_state,d.possible_cause,d.recommended_check,d.event_timestamp,d.risk_score,d.source_language,d.source_possible_cause,d.source_recommended_check,d.extended_attributes,e.hardware_version,e.bootloader_version,e.sw_version,e.coding,e.diagnostic_address,e.calibration_version,e.network,e.secure_boot,e.ota_state FROM raw.diagnostic_report r JOIN raw.dtc_event d ON d.report_id=r.report_id LEFT JOIN raw.ecu_version e ON e.report_id=r.report_id AND e.ecu_name=d.ecu_name;
CREATE OR REPLACE VIEW reporting.vw_environment_signal_detail AS SELECT d.dtc_event_id,r.file_id,r.file_name,r.sw_i_step,d.ecu_name,d.dtc_code,d.status,s.environment_signal_id,s.signal_name,s.signal_value,s.numeric_signal_value,s.event_timestamp FROM raw.environment_signal s JOIN raw.dtc_event d ON d.dtc_event_id=s.dtc_event_id JOIN raw.diagnostic_report r ON r.report_id=d.report_id;
CREATE OR REPLACE VIEW reporting.vw_test_summary AS SELECT r.report_id,r.file_id,r.file_name,r.vin,r.sw_i_step,t.test_start,t.test_end,t.test_type,t.test_environment,t.logger_id,t.reported_ecu_count,t.reported_total_dtcs,t.reported_active_dtcs,t.can_frames_captured,t.can_fd_frames_captured,t.ethernet_packets_captured,t.data_completeness,t.overall_result,t.disclaimer FROM raw.diagnostic_report r JOIN raw.vehicle_test_summary t ON t.report_id=r.report_id;
CREATE OR REPLACE VIEW reporting.vw_release_summary AS SELECT sw_i_step,COUNT(DISTINCT file_id) report_count,COUNT(*) dtc_count,COUNT(DISTINCT dtc_code) unique_dtc_count,COUNT(*) FILTER(WHERE status='Active') active_dtc_count,SUM(occurrence_counter) total_occurrences,COUNT(*)::numeric/NULLIF(COUNT(DISTINCT file_id),0) dtcs_per_report FROM reporting.vw_extended_dtc_detail GROUP BY sw_i_step;
CREATE OR REPLACE VIEW reporting.vw_ecu_health AS SELECT sw_i_step,ecu_name,COUNT(*) dtc_count,COUNT(DISTINCT dtc_code) unique_dtc_count,COUNT(*) FILTER(WHERE status='Active') active_dtc_count,SUM(occurrence_counter) total_occurrences,AVG(risk_score) average_risk,MAX(risk_score) maximum_risk FROM reporting.vw_extended_dtc_detail GROUP BY sw_i_step,ecu_name;
